fn query_snapshot_safe(db: &DistributedDb, query_key: &str) -> Option<Value> {
    let truetime = db.get_truetime(); // Returns [earliest, latest]
    let wait_time = truetime.latest - truetime.earliest;
    // Explicitly wait out the clock uncertainty before serving/reading
    std::thread::sleep(wait_time);
    db.read_at_snapshot(query_key, truetime.latest)
